import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for ParserBase.resetFloat.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class ParserBase_resetFloat_TriageGen0Test {

    private TestParserBase parserBase;

    // Subclass to expose protected method and access protected fields for verification
    private static class TestParserBase extends ParserBase {
        protected TestParserBase() {
            super(null, 0);
        }

        @Override
        protected void _closeInput() {}

        @Override
        protected void _releaseBuffers() {}

        @Override
        protected void _handleEOF() throws com.fasterxml.jackson.core.JsonParseException {
        }

        // Expose the method under test
        public JsonToken callResetFloat(boolean negative, int intLen, int fractLen, int expLen) {
            return resetFloat(negative, intLen, fractLen, expLen);
        }

        // Helper to access private/protected fields via reflection for assertion
        public Object getFieldValue(String fieldName) throws Exception {
            Field field = ParserBase.class.getDeclaredField(fieldName);
            field.setAccessible(true);
            return field.get(this);
        }
    }

    @Before
    public void setUp() {
        parserBase = new TestParserBase();
    }

    @Test
    public void testResetFloat_PositiveValues() throws Exception {
        // Arrange
        boolean negative = false;
        int intLen = 5;
        int fractLen = 2;
        int expLen = 3;

        // Act
        JsonToken result = parserBase.callResetFloat(negative, intLen, fractLen, expLen);

        // Assert
        assertEquals("Should return JsonToken.VALUE_NUMBER_FLOAT", JsonToken.VALUE_NUMBER_FLOAT, result);
        assertEquals("Negative flag should be false", false, parserBase.getFieldValue("_numberNegative"));
        assertEquals("Int length should be 5", 5, parserBase.getFieldValue("_intLength"));
        assertEquals("Fract length should be 2", 2, parserBase.getFieldValue("_fractLength"));
        assertEquals("Exp length should be 3", 3, parserBase.getFieldValue("_expLength"));

        // NR_UNKNOWN is typically 0 in Jackson's NumberType internal logic
        // We check if _numTypesValid was reset to the constant representing unknown
        assertEquals("Number type should be reset to unknown", 0, parserBase.getFieldValue("_numTypesValid"));
    }

    @Test
    public void testResetFloat_NegativeValues() throws Exception {
        // Arrange
        boolean negative = true;
        int intLen = 10;
        int fractLen = 10;
        int expLen = 10;

        // Act
        JsonToken result = parserBase.callResetFloat(negative, intLen, fractLen, expLen);

        // Assert
        assertEquals("Should return JsonToken.VALUE_NUMBER_FLOAT", JsonToken.VALUE_NUMBER_FLOAT, result);
        assertEquals("Negative flag should be true", true, parserBase.getFieldValue("_numberNegative"));
        assertEquals("Int length should be 10", 10, parserBase.getFieldValue("_intLength"));
        assertEquals("Fract length should be 10", 10, parserBase.getFieldValue("_fractLength"));
        assertEquals("Exp length should be 10", 10, parserBase.getFieldValue("_expLength"));
        assertEquals("Number type should be reset to unknown", 0, parserBase.getFieldValue("_numTypesValid"));
    }

    @Test
    public void testResetFloat_ZeroValues() throws Exception {
        // Arrange
        boolean negative = false;
        int intLen = 0;
        int fractLen = 0;
        int expLen = 0;

        // Act
        JsonToken result = parserBase.callResetFloat(negative, intLen, fractLen, expLen);

        // Assert
        assertEquals("Should return JsonToken.VALUE_NUMBER_FLOAT", JsonToken.VALUE_NUMBER_FLOAT, result);
        assertEquals("Int length should be 0", 0, parserBase.getFieldValue("_intLength"));
        assertEquals("Fract length should be 0", 0, parserBase.getFieldValue("_fractLength"));
        assertEquals("Exp length should be 0", 0, parserBase.getFieldValue("_expLength"));
    }
}
